#!/usr/bin/env node
/**
 * tests/adversarial-ui-m2-challenger2.js
 * 
 * Deep Empirical Adversarial Verification Harness for Milestone UI-M2
 * Challenger 2: Zero DOM Sink Security, XSS Fuzzing & Modal Focus Traps
 * Target: CineJoy LG webOS UI Modernization (1080p, webOS 8.5.0)
 * 
 * Conducts exhaustive empirical stress tests across 3 core dimensions:
 * 1. Static AST & Regex Zero DOM Sink Analysis (views, controllers, shell)
 * 2. Real-time XSS Payload Fuzzing into TMDB Data & Dynamic DOM Generation
 * 3. Modal Focus Trapping, Boundary Containment & Controlled Escapes
 */

'use strict';

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// 1. Resolve JSDOM across environment paths
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved:', e1.message);
      process.exit(1);
    }
  }
}

// 2. ANSI Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureList = [];

async function check(category, testName, fn) {
  totalChecks++;
  const idStr = totalChecks.toString().padStart(2, '0');
  const label = `[ADV-M2-CH2-${idStr}] [${category}] ${testName}`;
  const start = Date.now();
  try {
    await fn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
    console.error(`      ${C.red}Defect: ${err.message}${C.reset}`);
    failureList.push({ label, error: err.message, stack: err.stack });
  }
}

/**
 * Creates an integrated DOM environment loaded with app shell, navigation, and view controllers
 */
function createIntegratedDom(initialRoute = 'home') {
  const rootDir = path.resolve(__dirname, '..');
  const htmlPath = path.join(rootDir, 'app/index.html');
  const configPath = path.join(rootDir, 'app/js/config.js');
  const navPath = path.join(rootDir, 'app/js/navigation.js');
  const appPath = path.join(rootDir, 'app/js/app.js');
  const homePath = path.join(rootDir, 'app/js/views/home.js');
  const catalogPath = path.join(rootDir, 'app/js/views/catalog.js');
  const searchPath = path.join(rootDir, 'app/js/views/search.js');
  const detailsPath = path.join(rootDir, 'app/js/views/details.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#' + initialRoute,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  // Polyfills for TV headless environment
  if (!window.Element.prototype.scrollIntoView) {
    window.Element.prototype.scrollIntoView = function () {};
  }
  if (!window.Element.prototype.scrollTo) {
    window.Element.prototype.scrollTo = function () {};
  }

  // Layout geometry mock (1920x1080)
  window.Element.prototype.getBoundingClientRect = function () {
    // If element is hidden
    if (this.offsetParent === null && this.tagName !== 'BODY' && this.tagName !== 'HTML') {
      const style = window.getComputedStyle ? window.getComputedStyle(this) : {};
      if (style.display === 'none') {
        return { top: 0, left: 0, right: 0, bottom: 0, width: 0, height: 0, x: 0, y: 0 };
      }
    }

    // Default card or key dimensions
    if (this.classList.contains('key-btn')) {
      const isSpace = this.classList.contains('key-space');
      const isAction = this.classList.contains('key-action');
      const w = isSpace ? 420 : (isAction ? 132 : 72);
      return { top: 150, left: 100, right: 100 + w, bottom: 214, width: w, height: 64, x: 100, y: 150 };
    }
    if (this.classList.contains('card-poster')) {
      return { top: 400, left: 100, right: 320, bottom: 730, width: 220, height: 330, x: 100, y: 400 };
    }
    if (this.classList.contains('nav-pill-item')) {
      return { top: 20, left: 100, right: 220, bottom: 64, width: 120, height: 44, x: 100, y: 20 };
    }
    return { top: 100, left: 100, right: 300, bottom: 200, width: 200, height: 100, x: 100, y: 100 };
  };

  // Execute scripts in order
  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(homePath, 'utf8'));
  window.eval(fs.readFileSync(catalogPath, 'utf8'));
  window.eval(fs.readFileSync(searchPath, 'utf8'));
  window.eval(fs.readFileSync(detailsPath, 'utf8'));
  window.eval(fs.readFileSync(appPath, 'utf8'));

  return {
    dom,
    window,
    document: window.document,
    app: window.CinejoyApp,
    nav: window.SpatialNav,
    home: window.HomeViewController,
    catalog: window.CatalogViewController,
    movies: window.MoviesViewController,
    series: window.SeriesViewController,
    search: window.SearchViewController,
    details: window.DetailsViewController,
    cardFactory: window.CardFactory
  };
}

// =============================================================================
// MAIN TEST RUNNER
// =============================================================================
async function runAllTests() {
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}   CINEJOY-WEBOS: CHALLENGER 2 EMPIRICAL ADVERSARIAL VERIFICATION       ${C.reset}`);
  console.log(`${C.bold}${C.cyan}   Zero DOM Sinks, XSS Fuzzing, Modal Focus Traps & D-Pad Isolation     ${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================${C.reset}`);

  const rootDir = path.resolve(__dirname, '..');
  const viewFiles = ['home.js', 'catalog.js', 'search.js', 'details.js'];

  // ===========================================================================
  // SECTION 1: Automated AST & Regex Zero DOM Sink Analysis
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ AREA 1: Zero DOM Sink Static Analysis (app/js/views/*.js)${C.reset}`);

  await check('SINK', 'Zero .innerHTML Assignment Across app/js/views/*.js', async () => {
    for (const f of viewFiles) {
      const filePath = path.join(rootDir, 'app/js/views', f);
      const code = fs.readFileSync(filePath, 'utf8');
      // Match innerHTML assignments (allowing comments)
      const lines = code.split('\n');
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        if (/\/\//.test(line) && line.indexOf('innerHTML') > line.indexOf('//')) continue;
        if (/\.innerHTML\s*=/.test(line)) {
          throw new Error(`Dangerous innerHTML assignment in app/js/views/${f}:${i + 1} -> "${line.trim()}"`);
        }
      }
    }
  });

  await check('SINK', 'Zero .outerHTML Assignment Across app/js/views/*.js', async () => {
    for (const f of viewFiles) {
      const filePath = path.join(rootDir, 'app/js/views', f);
      const code = fs.readFileSync(filePath, 'utf8');
      const lines = code.split('\n');
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        if (/\/\//.test(line) && line.indexOf('outerHTML') > line.indexOf('//')) continue;
        if (/\.outerHTML\s*=/.test(line)) {
          throw new Error(`Dangerous outerHTML assignment in app/js/views/${f}:${i + 1} -> "${line.trim()}"`);
        }
      }
    }
  });

  await check('SINK', 'Zero document.write / document.writeln Across All Views & Shell', async () => {
    const checkPaths = [
      'app/js/views/home.js',
      'app/js/views/catalog.js',
      'app/js/views/search.js',
      'app/js/views/details.js',
      'app/js/app.js',
      'app/js/navigation.js',
      'app/index.html'
    ];
    for (const p of checkPaths) {
      const content = fs.readFileSync(path.join(rootDir, p), 'utf8');
      assert(!/document\.write\s*\(/.test(content), `Dangerous document.write found in ${p}`);
      assert(!/document\.writeln\s*\(/.test(content), `Dangerous document.writeln found in ${p}`);
    }
  });

  await check('SINK', 'Zero eval() or Function() Dynamic Execution Sinks Across All Views', async () => {
    for (const f of viewFiles) {
      const filePath = path.join(rootDir, 'app/js/views', f);
      const code = fs.readFileSync(filePath, 'utf8');
      assert(!/(?<!\w)eval\s*\(/.test(code), `Dangerous eval() call found in app/js/views/${f}`);
      assert(!/new\s+Function\s*\(/.test(code), `Dangerous new Function() call found in app/js/views/${f}`);
      assert(!/(?<!\w)Function\s*\(/.test(code), `Dangerous Function() call found in app/js/views/${f}`);
    }
  });

  await check('SINK', 'Zero insertAdjacentHTML Calls Across All Views', async () => {
    for (const f of viewFiles) {
      const filePath = path.join(rootDir, 'app/js/views', f);
      const code = fs.readFileSync(filePath, 'utf8');
      assert(!/insertAdjacentHTML\s*\(/.test(code), `Dangerous insertAdjacentHTML call in app/js/views/${f}`);
    }
  });

  await check('SINK', 'Zero Computed Member Property Sinks (e.g. el["inner" + "HTML"])', async () => {
    for (const f of viewFiles) {
      const filePath = path.join(rootDir, 'app/js/views', f);
      const code = fs.readFileSync(filePath, 'utf8');
      assert(!/\[\s*['"`]inner['"`]\s*\+\s*['"`]HTML['"`]\s*\]/.test(code), `Obfuscated innerHTML sink in ${f}`);
      assert(!/\[\s*['"`]outer['"`]\s*\+\s*['"`]HTML['"`]\s*\]/.test(code), `Obfuscated outerHTML sink in ${f}`);
    }
  });

  // ===========================================================================
  // SECTION 2: Empirical XSS Payload Fuzzing into TMDB Data & View Rendering
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ AREA 2: Empirical XSS Payload Fuzzing in Mock TMDB Rendering${C.reset}`);

  // Test Payloads
  const XSS_PAYLOADS = [
    '<script id="xss-pwn-1">window.__XSS_PWNED_1 = true;</script>',
    '<img src="bogus-img.jpg" onerror="window.__XSS_PWNED_2 = true;">',
    '<svg onload="window.__XSS_PWNED_3 = true;"><circle r="10"/></svg>',
    '"><b id="xss-pwn-4">breakout</b><iframe src="javascript:window.__XSS_PWNED_4=true"></iframe>',
    'javascript:window.__XSS_PWNED_5=true',
    '\u202E<script id="xss-pwn-6">window.__XSS_PWNED_6 = true;</script>',
    '\u0000<script id="xss-pwn-7">window.__XSS_PWNED_7 = true;</script>',
    '🎬 🍿 & < > " \' / \\ $ % ; { } [ ] ' + 'X'.repeat(5000)
  ];

  await check('XSS', 'CardFactory.createPosterCard Renders XSS Payloads Without DOM Sinks', async () => {
    const { window, cardFactory } = createIntegratedDom();
    assert(cardFactory, 'CardFactory must be loaded');

    for (let i = 0; i < XSS_PAYLOADS.length; i++) {
      const payload = XSS_PAYLOADS[i];
      const mockItem = {
        id: 100 + i,
        title: 'Title ' + payload,
        overview: 'Overview ' + payload,
        release_date: '2026-01-01',
        vote_average: 8.5,
        ratingDisplay: payload,
        genres: [payload, 'Action'],
        poster_path: '/poster.jpg'
      };

      const card = cardFactory.createPosterCard(mockItem, 'test-shelf', i, { genreText: payload });
      window.document.body.appendChild(card);

      // Verify no script tags or iframe injected
      assert(!window.document.getElementById('xss-pwn-1'), 'Script tag injected by createPosterCard!');
      assert(!window.document.getElementById('xss-pwn-4'), 'Breakout tag injected by createPosterCard!');
      assert(!window.document.getElementById('xss-pwn-6'), 'Unicode bidi script injected!');
      assert(!window.document.getElementById('xss-pwn-7'), 'Null-byte script injected!');
      assert(!window.__XSS_PWNED_1, 'Payload 1 executed!');
      assert(!window.__XSS_PWNED_2, 'Payload 2 executed!');
      assert(!window.__XSS_PWNED_3, 'Payload 3 executed!');

      // Verify textContent contains payload verbatim without executing
      const titleEl = card.querySelector('.poster-title');
      assert.strictEqual(titleEl.textContent, 'Title ' + payload, 'Title textContent must match verbatim');
      assert(titleEl.innerHTML.includes('&lt;') || !titleEl.innerHTML.includes('<script'), 'Title innerHTML escaped');

      card.remove();
    }
  });

  await check('XSS', 'CardFactory.createEpisodeCard Renders XSS Payloads Safely as Text', async () => {
    const { window, cardFactory } = createIntegratedDom();

    for (let i = 0; i < XSS_PAYLOADS.length; i++) {
      const payload = XSS_PAYLOADS[i];
      const mockEpisode = {
        episode_number: i + 1,
        name: 'Ep ' + payload,
        overview: 'Synopsis ' + payload,
        runtime: 45,
        still_path: '/still.jpg'
      };

      const card = cardFactory.createEpisodeCard(mockEpisode, 1, i);
      window.document.body.appendChild(card);

      assert(!window.document.getElementById('xss-pwn-1'), 'Script tag injected by createEpisodeCard!');
      assert(!window.document.getElementById('xss-pwn-4'), 'Breakout tag injected by createEpisodeCard!');
      assert(!window.__XSS_PWNED_1);
      assert(!window.__XSS_PWNED_2);
      assert(!window.__XSS_PWNED_3);

      const titleEl = card.querySelector('.episode-title');
      assert(titleEl.textContent.includes('Ep ' + payload));
      const overviewEl = card.querySelector('.episode-overview');
      assert.strictEqual(overviewEl.textContent, 'Synopsis ' + payload);

      card.remove();
    }
  });

  await check('XSS', 'CardFactory.createCastCard Renders XSS Payloads Safely as Text', async () => {
    const { window, cardFactory } = createIntegratedDom();

    for (let i = 0; i < XSS_PAYLOADS.length; i++) {
      const payload = XSS_PAYLOADS[i];
      const mockActor = {
        name: 'Actor ' + payload,
        character: 'Role ' + payload,
        profile_path: '/actor.jpg'
      };

      const card = cardFactory.createCastCard(mockActor, i);
      window.document.body.appendChild(card);

      assert(!window.document.getElementById('xss-pwn-1'), 'Script tag injected by createCastCard!');
      assert(!window.__XSS_PWNED_1);
      assert(!window.__XSS_PWNED_2);

      const nameEl = card.querySelector('.cast-name');
      assert.strictEqual(nameEl.textContent, 'Actor ' + payload);
      const roleEl = card.querySelector('.cast-role');
      if (roleEl) {
        assert.strictEqual(roleEl.textContent, 'Role ' + payload);
      }

      card.remove();
    }
  });

  await check('XSS', 'HomeViewController.bindHeroBanner Renders Payloads with Zero Sinks', async () => {
    const { window, home } = createIntegratedDom('home');
    home.init();

    const payload = '<script id="hero-xss">window.__HERO_PWNED = true;</script>';
    const mockHeroItem = {
      id: 999,
      title: 'Hero ' + payload,
      overview: 'Hero Synopsis ' + payload,
      vote_average: 9.2,
      release_date: '2026-05-10',
      backdrop_path: '/backdrop.jpg'
    };

    home.bindHeroBanner(mockHeroItem);

    assert(!window.__HERO_PWNED, 'Hero banner XSS executed!');
    assert(!window.document.getElementById('hero-xss'), 'Hero banner injected script element!');

    const titleEl = window.document.querySelector('.hero-title-fallback');
    assert.strictEqual(titleEl.textContent, 'Hero ' + payload);
    const synopsisEl = window.document.querySelector('.hero-synopsis');
    assert.strictEqual(synopsisEl.textContent, 'Hero Synopsis ' + payload);
  });

  await check('XSS', 'HomeViewController.renderShelf Renders 20 Payload Cards with Zero Execution', async () => {
    const { window, home } = createIntegratedDom('home');
    home.init();

    const items = [];
    for (let i = 0; i < 20; i++) {
      items.push({
        id: 200 + i,
        title: `Trending <img src=x onerror="window.__SHELF_PWNED_${i}=true"> ${i}`,
        overview: `Overview <script>window.__SHELF_PWNED_${i}=true</script>`,
        release_date: '2026-01-01',
        vote_average: 8.0,
        poster_path: '/poster.jpg'
      });
    }

    home.renderShelf('shelf-trending-movies', items, 'movie');

    const shelfSection = window.document.getElementById('shelf-trending-movies');
    assert(shelfSection, 'Trending shelf section must exist');
    const cards = shelfSection.querySelectorAll('.card-poster');
    assert.strictEqual(cards.length, 20, 'Expected exactly 20 cards in shelf rail');

    for (let i = 0; i < 20; i++) {
      assert(!window[`__SHELF_PWNED_${i}`], `Shelf payload ${i} executed!`);
    }
  });

  await check('XSS', 'CatalogViewController Renders Payloads in Genre Pills and Grid Cards', async () => {
    const { window, movies } = createIntegratedDom('movies');
    movies.init();

    // Mock Discover response with payloads
    const payloadItems = [
      { id: 301, title: 'Movie 1 <script id="cat-pwn">window.__CAT_PWNED=1;</script>', poster_path: '/p.jpg' },
      { id: 302, title: 'Movie 2 <img src=x onerror="window.__CAT_PWNED=2;">', poster_path: '/p.jpg' }
    ];

    movies.renderGrid(payloadItems, true);

    assert(!window.__CAT_PWNED, 'Catalog grid XSS executed!');
    assert(!window.document.getElementById('cat-pwn'), 'Catalog grid injected script node!');

    const cards = window.document.querySelectorAll('#view-movies .content-grid-6col .card-poster');
    assert.strictEqual(cards.length, 2, 'Two cards rendered');
    assert.strictEqual(cards[0].querySelector('.poster-title').textContent, payloadItems[0].title);
  });

  await check('XSS', 'SearchViewController Renders Payloads Safely in Empty and Results States', async () => {
    const { window, search } = createIntegratedDom('search');
    search.init();

    const xssQuery = '<script id="search-xss">window.__SEARCH_PWNED=1;</script>';
    search.query = xssQuery;
    search.updateInputDisplay();

    const queryDisplay = window.document.getElementById('search-query-text');
    assert.strictEqual(queryDisplay.textContent, xssQuery, 'search-query-text must match verbatim');
    assert(!window.__SEARCH_PWNED, 'Search query text executed script!');

    // Test Empty State Rendering
    search.renderResults([]);
    const emptyMsg = window.document.querySelector('.search-empty-state');
    assert(emptyMsg, 'Search empty state created');
    assert(emptyMsg.textContent.includes('No results found for "' + xssQuery + '"'));
    assert(!window.document.getElementById('search-xss'), 'Search empty state created script node!');

    // Test Results Rendering with Payloads
    const searchResults = [
      { id: 401, title: 'Search Result <svg onload="window.__SEARCH_RES=1;">', poster_path: '/s.jpg' }
    ];
    search.renderResults(searchResults);
    assert(!window.__SEARCH_RES, 'Search result SVG onload executed!');
    const resultCard = window.document.querySelector('#search-results-grid .card-poster');
    assert(resultCard, 'Search result card rendered');
    assert.strictEqual(resultCard.querySelector('.poster-title').textContent, searchResults[0].title);
  });

  await check('XSS', 'DetailsViewController Renders Payloads in Hero, Meta, Cast, & Episodes', async () => {
    const { window, details } = createIntegratedDom('details');
    details.init();

    const payload = '<script id="details-xss">window.__DETAILS_PWNED = true;</script>';
    const mockDetails = {
      id: 501,
      title: 'Details ' + payload,
      overview: 'Overview ' + payload,
      vote_average: 8.8,
      release_date: '2026-03-15',
      runtime: 142,
      quality: '4K ' + payload,
      backdrop_path: '/backdrop.jpg'
    };

    details.bindHero(mockDetails, 'movie');

    assert(!window.__DETAILS_PWNED, 'Details hero XSS executed!');
    assert(!window.document.getElementById('details-xss'), 'Details script node injected!');

    assert.strictEqual(window.document.getElementById('details-title').textContent, 'Details ' + payload);
    assert.strictEqual(window.document.getElementById('details-overview').textContent, 'Overview ' + payload);
    assert.strictEqual(window.document.getElementById('details-meta-quality').textContent, '4K ' + payload);

    // Test Cast Rendering
    const cast = [
      { name: 'Actor ' + payload, character: 'Role ' + payload, profile_path: '/cast.jpg' }
    ];
    details.renderCast(cast);
    assert(!window.__DETAILS_PWNED);
    const castName = window.document.querySelector('#details-cast-rail .cast-name');
    assert(castName && castName.textContent === 'Actor ' + payload);

    // Test Episodes Rendering
    const episodes = [
      { episode_number: 1, name: 'Ep ' + payload, overview: 'Ep Overview ' + payload, runtime: 55 }
    ];
    details.renderEpisodes(episodes, 1);
    assert(!window.__DETAILS_PWNED);
    const epTitle = window.document.querySelector('#details-episodes-rail .episode-title');
    assert(epTitle && epTitle.textContent.includes('Ep ' + payload));
  });

  // ===========================================================================
  // SECTION 3: Modal Focus Trapping, Boundaries & Isolation
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ AREA 3: Modal Focus Trapping & SpatialNav Isolation${C.reset}`);

  await check('TRAP', 'Search View Activation Engages Virtual Keyboard Focus Trap', async () => {
    const { app, nav, document } = createIntegratedDom('home');
    app.init();

    // Switch to search
    app.switchView('search');

    assert.strictEqual(nav.isTrapped(), true, 'SpatialNav must be trapped on search view activation');
    const focused = nav.getCurrentFocus();
    assert(focused, 'A key button must be focused on search entry');
    const kbContainer = document.querySelector('.tv-keyboard-container');
    assert(kbContainer.contains(focused), 'Initial focus must be inside .tv-keyboard-container');
  });

  await check('TRAP', 'Virtual Keyboard Trap Blocks ArrowUp from Escaping to Header', async () => {
    const { app, nav, document } = createIntegratedDom('search');
    app.init();
    app.switchView('search');

    // Focus top row key '1'
    const key1 = document.querySelector('.key-btn[data-key="1"]');
    assert(key1, 'Key 1 must exist');
    nav.setFocus(key1);
    assert.strictEqual(nav.getCurrentFocus(), key1);

    // Move Up - must be blocked by trap
    const upTarget = nav.move('up');
    assert.strictEqual(upTarget, null, 'Moving UP from top keyboard row must return null');
    assert.strictEqual(nav.getCurrentFocus(), key1, 'Focus must remain on key 1');

    const headerActive = document.querySelector('.nav-pill-item.active');
    assert.strictEqual(headerActive.classList.contains('focused'), false, 'Header must NOT receive focus');
  });

  await check('TRAP', 'Virtual Keyboard Trap Blocks ArrowLeft & ArrowRight Lateral Escapes', async () => {
    const { app, nav, document } = createIntegratedDom('search');
    app.init();
    app.switchView('search');

    // Leftmost key 'Q'
    const keyQ = document.querySelector('.key-btn[data-key="Q"]');
    nav.setFocus(keyQ);
    const leftTarget = nav.move('left');
    assert.strictEqual(leftTarget, null, 'Moving LEFT from leftmost key must be blocked');
    assert.strictEqual(nav.getCurrentFocus(), keyQ);

    // Rightmost key 'P'
    const keyP = document.querySelector('.key-btn[data-key="P"]');
    nav.setFocus(keyP);
    const rightTarget = nav.move('right');
    assert.strictEqual(rightTarget, null, 'Moving RIGHT from rightmost key must be blocked');
    assert.strictEqual(nav.getCurrentFocus(), keyP);
  });

  await check('TRAP', 'Virtual Keyboard Trap Blocks ArrowDown When Results Are Empty', async () => {
    const { app, nav, search, document } = createIntegratedDom('search');
    app.init();
    app.switchView('search');

    search.renderResults([]); // Empty results

    const spaceKey = document.querySelector('.key-btn[data-key="SPACE"]');
    assert(spaceKey, 'SPACE key exists');
    nav.setFocus(spaceKey);

    const downTarget = nav.move('down');
    assert.strictEqual(downTarget, null, 'Moving DOWN from bottom row without results must be blocked');
    assert.strictEqual(nav.getCurrentFocus(), spaceKey, 'Focus must remain on SPACE key');
    assert.strictEqual(nav.isTrapped(), true, 'SpatialNav must remain trapped');
  });

  await check('TRAP', 'Controlled Down Escape to Search Results Untraps SpatialNav', async () => {
    const { app, nav, search, window, document } = createIntegratedDom('search');
    app.init();
    app.switchView('search');

    // Populate search results
    const mockResults = [
      { id: 901, title: 'Interstellar', poster_path: '/inter.jpg' },
      { id: 902, title: 'Inception', poster_path: '/incep.jpg' }
    ];
    search.renderResults(mockResults);

    const firstCard = document.querySelector('#search-results-grid .card-poster');
    assert(firstCard, 'First search result card must exist in DOM');

    // Focus SPACE key on bottom row
    const spaceKey = document.querySelector('.key-btn[data-key="SPACE"]');
    nav.setFocus(spaceKey);
    assert.strictEqual(nav.isTrapped(), true);

    // Press ArrowDown on keyboard button
    const evt = new window.KeyboardEvent('keydown', { key: 'ArrowDown', bubbles: true });
    spaceKey.dispatchEvent(evt);

    assert.strictEqual(nav.isTrapped(), false, 'SpatialNav trap must be released on escape to results');
    assert.strictEqual(nav.getCurrentFocus(), firstCard, 'First result card must receive focus');
  });

  await check('TRAP', 'Switching View from Search to Home Cleanly Releases Trap', async () => {
    const { app, nav, document } = createIntegratedDom('search');
    app.init();
    app.switchView('search');
    assert.strictEqual(nav.isTrapped(), true);

    app.switchView('home');
    assert.strictEqual(nav.isTrapped(), false, 'Navigating away from search must untrap SpatialNav');

    const heroPlay = document.getElementById('hero-play-btn');
    const success = nav.setFocus(heroPlay);
    assert.strictEqual(success, true, 'Hero play button in home view must now be focusable');
    assert.strictEqual(nav.getCurrentFocus(), heroPlay);
  });

  await check('TRAP', 'Details View Focus Isolation: Inactive Views Are Excluded From Navigation', async () => {
    const { app, nav, document } = createIntegratedDom('home');
    app.init();

    // Open details view
    app.openDetails({ title: 'Dune: Part Two', year: '2024', rating: '8.6' });
    assert.strictEqual(app.state.currentView, 'details');

    const activeView = document.getElementById('view-details');
    assert(activeView.classList.contains('active'), '#view-details must be active');

    // Verify candidates query does NOT include home cards
    const candidates = nav.getCandidates();
    for (const c of candidates) {
      const parentView = c.closest('.view');
      if (parentView) {
        assert.strictEqual(parentView.id, 'view-details', `Navigable candidate "${c.className}" was found in inactive view ${parentView.id}!`);
      }
    }
  });

  await check('NAV', 'Details View Remote Back Key Hierarchy: Returns to Origin View Without Loops', async () => {
    const { app } = createIntegratedDom('home');
    app.init();

    // 1. Home -> Details -> Back -> Home
    app.openDetails({ title: 'Item 1' });
    assert.strictEqual(app.state.currentView, 'details');
    app.handleBackNavigation();
    assert.strictEqual(app.state.currentView, 'home', 'Back from details must return to home');

    // 2. Movies -> Details -> Back -> Movies
    app.switchView('movies');
    app.openDetails({ title: 'Item 2' });
    assert.strictEqual(app.state.currentView, 'details');
    assert.strictEqual(app.state.detailsOriginView, 'movies');
    app.handleBackNavigation();
    assert.strictEqual(app.state.currentView, 'movies', 'Back from details must return to movies origin');

    // 3. Series -> Details 1 -> Related Details 2 -> Back -> Series
    app.switchView('series');
    app.openDetails({ title: 'Series 1' });
    app.openDetails({ title: 'Series 2 (Related)' });
    assert.strictEqual(app.state.currentView, 'details');
    app.handleBackNavigation();
    assert.strictEqual(app.state.currentView, 'series', 'Back after related details must return to origin series');

    // 4. Details -> Player -> Exit Player -> Details -> Back -> Origin
    app.switchView('home');
    app.openDetails({ title: 'Movie 3' });
    app.switchView('player');
    assert.strictEqual(app.state.currentView, 'player');
    app.exitPlayer();
    assert.strictEqual(app.state.currentView, 'details');
    app.handleBackNavigation();
    assert.strictEqual(app.state.currentView, 'home', 'Ping-pong loop prevented: 2nd back returns to home');
  });

  await check('INVARIANT', 'Details View Preserves All 11 Invariant DOM IDs', async () => {
    const { document } = createIntegratedDom('details');
    const requiredIds = [
      'details-title',
      'details-meta-rating',
      'details-meta-year',
      'details-meta-runtime',
      'details-meta-quality',
      'details-overview',
      'details-play-btn',
      'details-season-selector',
      'details-episodes-shelf',
      'details-cast-shelf',
      'details-backdrop-img'
    ];

    for (const id of requiredIds) {
      const el = document.getElementById(id);
      assert(el, `Mandatory DOM ID #${id} is missing in Details view!`);
    }
  });

  // ===========================================================================
  // SUMMARY & VERDICT
  // ===========================================================================
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}► CHALLENGER 2 ADVERSARIAL TEST RESULTS SUMMARY${C.reset}`);
  console.log('------------------------------------------------------------------------');
  console.log(`  Total Adversarial Checks Run:  ${totalChecks}`);
  console.log(`  Passed Checks:                ${C.green}${C.bold}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:                ${failedChecks > 0 ? `${C.red}${C.bold}${failedChecks}` : '0'}${C.reset}`);
  console.log('------------------------------------------------------------------------');

  if (failedChecks > 0) {
    console.log(`\n${C.red}${C.bold}VERDICT: REJECT (${failedChecks} defect(s) detected)${C.reset}\n`);
    for (const f of failureList) {
      console.error(`- ${f.label}: ${f.error}`);
    }
    process.exit(1);
  } else {
    console.log(`\n${C.green}${C.bold}VERDICT: APPROVE (100% of ${passedChecks} adversarial checks passed)${C.reset}\n`);
    process.exit(0);
  }
}

runAllTests().catch((err) => {
  console.error('Fatal execution error:', err);
  process.exit(1);
});

