// Layout geometry mock with accurate 2D spatial coordinates
window.Element.prototype.getBoundingClientRect = function () {
  if (this.style && this.style.display === 'none') {
    return { top: 0, left: 0, right: 0, bottom: 0, width: 0, height: 0, x: 0, y: 0 };
  }

  // Keyboard buttons with accurate row and column layout
  if (this.classList.contains('key-btn')) {
    const rowEl = this.closest('.keyboard-row');
    const rIdx = rowEl && rowEl.parentElement ? Array.from(rowEl.parentElement.children).indexOf(rowEl) : 0;
    const cIdx = rowEl ? Array.from(rowEl.children).indexOf(this) : 0;
    const isSpace = this.classList.contains('key-space');
    const isAction = this.classList.contains('key-action');
    const w = isSpace ? 360 : (isAction ? 132 : 72);
    const left = 96 + cIdx * 80;
    const top = 220 + rIdx * 70;
    return { top, left, right: left + w, bottom: top + 64, width: w, height: 64, x: left, y: top };
  }

