await check('INVARIANT', 'Details View Preserves Critical Invariant DOM IDs & Controls', async () => {
  const { document } = createIntegratedDom('details');
  const requiredStaticIds = [
    'details-title',
    'details-meta-rating',
    'details-meta-year',
    'details-play-btn',
    'details-cast-rail',
    'details-episodes-rail',
    'details-recommendations-rail'
  ];

  for (const id of requiredStaticIds) {
    const el = document.getElementById(id);
    assert(el, `Mandatory DOM ID #${id} is missing in Details view!`);
  }

  const backdropEl = document.getElementById('details-backdrop-img') || document.querySelector('.details-backdrop-img');
  assert(backdropEl, 'Backdrop image element must be present in Details view');

  const synopsisEl = document.getElementById('details-overview') || document.querySelector('.details-synopsis');
  assert(synopsisEl, 'Synopsis container must be present in Details view');

  const playBtn = document.getElementById('details-play-btn');
  assert.strictEqual(playBtn.getAttribute('data-nav'), 'true', 'Details play button must be navigable');
  assert.strictEqual(playBtn.getAttribute('data-nav-group'), 'details-actions', 'Details play button must belong to details-actions group');
});

